#include <stdio.h>

typedef struct {
    int x;
    int y;
} Point;

int distance_squared(Point a, Point b) {
    int dx = a.x - b.x;
    int dy = a.y - b.y;
    return dx * dx + dy * dy;
}

int main() {
    Point p = {1, 2};
    Point q = {4, 6};
    printf("Squared distance = %d\n", distance_squared(p, q));
    return 0;
}
